  ('731de5f9-72ea-5a79-9773-0febcd741b85', 'd6d861cb-e0f0-5072-a443-90b256a47eb7', 'Army', 'officer', '42H', 'SENIOR HUMAN RESOURCES OFFICER', 'training', 'O-5', null, 'Lieutenant Colonel development — Education', 'Adjutant General Branch officer career pamphlet, DA PAM 600-3 chapter (26 January 2026)', 'Lieutenant colonels selected for CSL, ACoS G-1, or battalion command attend pre- command courses and prepare to attend Senior Service College (SSC) upon successful completion of CSL and become JPME II qualified.', '118c9fd975db18a394ad3561ff7499d4f3df4222169fa78264ca9e9d86b7f3ae', 10, 10, '10', 134, null, null, false, null),
  ('c832a2df-b0ca-526d-83a9-958897ebdc16', 'd6d861cb-e0f0-5072-a443-90b256a47eb7', 'Army', 'officer', '42H', 'SENIOR HUMAN RESOURCES OFFICER', 'assignments', 'O-5', null, 'Lieutenant Colonel development — Career Developmental Assignments', 'Adjutant General Branch officer career pamphlet, DA PAM 600-3 chapter (26 January 2026)', '(a) G–1 (CSL Designated).
(b) Battalion Commander (CSL Designated).
(c) Chief, Innovation Division, HRC (CSL Designated).
(d) 42C - Commander, USMA Band.', '44e877c5d2768f22fd8500795f7630cda7a1bdd7a47ad5d35a4c613f0f5003e2', 10, 10, '10', 135, null, null, false, null),
  ('0aa0aa93-91b9-5fdb-86d5-9d261617c200', 'd6d861cb-e0f0-5072-a443-90b256a47eb7', 'Army', 'officer', '42H', 'SENIOR HUMAN RESOURCES OFFICER', 'assignments', 'O-5', null, 'Lieutenant Colonel development — Broadening Assignments', 'Adjutant General Branch officer career pamphlet, DA PAM 600-3 chapter (26 January 2026)', 'Broadening Assignments
(a) AG School Director of Training/Proponent Chief.
(b) HRC TADD/DA SEC/Other HRC Staff. *
(c) TPOC Chief.
(d) SSI Division Chief (Proponent and Leader Development, Director of Training, Force Modernization, Concepts and Doctrine). *
