  ('b56acdad-fece-5719-9bc8-d0c22e1dd91b', 'd6d861cb-e0f0-5072-a443-90b256a47eb7', 'Army', 'officer', '42H', 'SENIOR HUMAN RESOURCES OFFICER', 'training', 'O-6', null, 'Colonel development — Education', 'Adjutant General Branch officer career pamphlet, DA PAM 600-3 chapter (26 January 2026)', 'If not already complete, colonels should attend SSC.', 'ceb1718943442829dc729e38e644af5152d2542b5f338105d60cef63298436ae', 11, 11, '11', 143, null, null, false, null),
